def assign_categories(apps, schema_editor):
    Category = apps.get_model("sales", "AccessoryCategory")
    Product = apps.get_model("sales", "AccessoryProduct")
    for index, (name, products) in enumerate(CATEGORY_PLAN, start=1):
        category, _created = Category.objects.get_or_create(name=name, defaults={"sort_order": index * 10})
        Product.objects.filter(name__in=products, category__isnull=True).update(category=category)


